#!/usr/bin/env node
// POSSE: Publish (on your) Own Site, Syndicate Elsewhere.
//
// Reads the list of published posts from your site's /posse.json (generated by
// src/pages/posse.json.ts at build time) and posts any that haven't been shared
// yet to Bluesky and, optionally, Mastodon.
//
// It is idempotent: before posting, it looks at your recent Bluesky/Mastodon
// posts and skips any article whose URL is already there. So it's safe to run
// on every deploy, and if one run fails, the next one will catch up.
//
// Usage:
//   node scripts/posse.mjs                 # syndicate from the live site
//   node scripts/posse.mjs --dry-run       # show what would be posted, post nothing
//   node scripts/posse.mjs --local         # read _site/posse.json (after `npm run build`)
//   node scripts/posse.mjs --only <slug>   # consider only this post
//
// Environment (GitHub repo secrets in CI, or a local .env you `source`):
//   BLUESKY_APP_PASSWORD   app password from bsky.app > Settings > App passwords
//   BLUESKY_SERVICE        optional, your PDS (default https://bsky.social)
//   MASTODON_TOKEN         optional, access token with write:statuses + read:accounts
//
// Handles, the Mastodon instance and the cutoff date live in engine/config.mjs
// (posse section) and are published inside posse.json.

import { readFile, appendFile } from "node:fs/promises";

const args = process.argv.slice(2);
const DRY_RUN = args.includes("--dry-run");
const LOCAL = args.includes("--local");
const ONLY = args.includes("--only") ? args[args.indexOf("--only") + 1] : null;

const log = (...m) => console.log(...m);
const summary = [];

// ---------------------------------------------------------------------------
// Loading the feed
// ---------------------------------------------------------------------------

async function siteUrlFromConfig() {
  const { default: config } = await import("../engine/config.mjs");
  return (config.origin + config.base).replace(/\/$/, "");
}

async function loadFeed() {
  if (LOCAL) {
    const raw = await readFile(new URL("../_site/posse.json", import.meta.url), "utf8");
    return JSON.parse(raw);
  }
  const url = `${await siteUrlFromConfig()}/posse.json?t=${Date.now()}`;
  const res = await fetch(url, { headers: { "cache-control": "no-cache" } });
  if (!res.ok) throw new Error(`Fetching ${url} failed: ${res.status}`);
  return res.json();
}

/** Wait until the article is actually reachable (GitHub Pages can lag a little). */
async function waitUntilLive(url, tries = 8) {
  if (LOCAL) return true;
  for (let i = 0; i < tries; i++) {
    const res = await fetch(`${url}?t=${Date.now()}`, { method: "HEAD" }).catch(() => null);
    if (res?.ok) return true;
    await new Promise((r) => setTimeout(r, 15_000));
  }
  return false;
}

// ---------------------------------------------------------------------------
// Text helpers
// ---------------------------------------------------------------------------

const segmenter = new Intl.Segmenter("en", { granularity: "grapheme" });
const graphemes = (s) => [...segmenter.segment(s)].map((x) => x.segment);

function truncate(text, max) {
  const g = graphemes(text);
  if (g.length <= max) return text;
  return g.slice(0, max - 1).join("").trimEnd() + "…";
}

function postText(post, max) {
  if (post.text) return truncate(post.text, max);
  const body = post.shortDescription || post.description || "";
  return truncate(body ? `${post.title}\n\n${body}` : post.title, max);
}

// ---------------------------------------------------------------------------
// Bluesky (plain XRPC over fetch)
// ---------------------------------------------------------------------------

const bluesky = {
  name: "Bluesky",

  enabled(feed) {
    return Boolean(feed.bluesky?.handle && process.env.BLUESKY_APP_PASSWORD);
  },

  async init(feed) {
    this.service = process.env.BLUESKY_SERVICE || "https://bsky.social";
    this.handle = feed.bluesky.handle;
    if (DRY_RUN && !process.env.BLUESKY_APP_PASSWORD) return;
    const res = await fetch(`${this.service}/xrpc/com.atproto.server.createSession`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ identifier: this.handle, password: process.env.BLUESKY_APP_PASSWORD }),
    });
    if (!res.ok) throw new Error(`Bluesky login failed: ${res.status} ${await res.text()}`);
    this.session = await res.json();
  },

  /** URLs of articles already linked from your Bluesky posts. */
  async alreadyShared() {
    const urls = new Set();
    let cursor;
    for (let page = 0; page < 5; page++) {
      const q = new URLSearchParams({ actor: this.handle, limit: "100", filter: "posts_no_replies" });
      if (cursor) q.set("cursor", cursor);
      const res = await fetch(`https://public.api.bsky.app/xrpc/app.bsky.feed.getAuthorFeed?${q}`);
      if (!res.ok) throw new Error(`Reading Bluesky feed failed: ${res.status}`);
      const data = await res.json();
      for (const { post } of data.feed) {
        const uri = post.record?.embed?.external?.uri ?? post.embed?.external?.uri;
        if (uri) urls.add(uri);
        for (const f of post.record?.facets ?? [])
          for (const feat of f.features ?? []) if (feat.uri) urls.add(feat.uri);
      }
      cursor = data.cursor;
      if (!cursor) break;
    }
    return urls;
  },

  async uploadThumb(imageUrl) {
    try {
      const img = await fetch(imageUrl);
      if (!img.ok) return undefined;
      const bytes = new Uint8Array(await img.arrayBuffer());
      if (bytes.byteLength > 976_000) return undefined; // Bluesky limit is ~1 MB
      const res = await fetch(`${this.service}/xrpc/com.atproto.repo.uploadBlob`, {
        method: "POST",
        headers: {
          "content-type": img.headers.get("content-type") || "image/png",
          authorization: `Bearer ${this.session.accessJwt}`,
        },
        body: bytes,
      });
      if (!res.ok) return undefined;
      return (await res.json()).blob;
    } catch {
      return undefined;
    }
  },

  async publish(post, feed) {
    const text = postText(post, 300);
    if (DRY_RUN) return { text, url: "(dry run)" };
    const thumb = await this.uploadThumb(post.image);
    const record = {
      $type: "app.bsky.feed.post",
      text,
      createdAt: new Date().toISOString(),
      langs: [feed.lang || "en"],
      embed: {
        $type: "app.bsky.embed.external",
        external: {
          uri: post.url,
          title: post.title,
          description: post.description ?? "",
          ...(thumb ? { thumb } : {}),
        },
      },
    };
    const res = await fetch(`${this.service}/xrpc/com.atproto.repo.createRecord`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${this.session.accessJwt}`,
      },
      body: JSON.stringify({ repo: this.session.did, collection: "app.bsky.feed.post", record }),
    });
    if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
    const { uri } = await res.json();
    const [, , did, , rkey] = uri.split("/");
    return { text, url: `https://bsky.app/profile/${did}/post/${rkey}` };
  },
};

// ---------------------------------------------------------------------------
// Mastodon (REST API)
// ---------------------------------------------------------------------------

const mastodon = {
  name: "Mastodon",

  enabled(feed) {
    return Boolean(feed.mastodon?.instance && process.env.MASTODON_TOKEN);
  },

  async init(feed) {
    this.base = feed.mastodon.instance.replace(/\/$/, "");
    this.headers = { authorization: `Bearer ${process.env.MASTODON_TOKEN}` };
    const res = await fetch(`${this.base}/api/v1/accounts/verify_credentials`, { headers: this.headers });
    if (!res.ok) throw new Error(`Mastodon login failed: ${res.status}`);
    this.account = await res.json();
  },

  async alreadyShared() {
    const urls = new Set();
    const res = await fetch(
      `${this.base}/api/v1/accounts/${this.account.id}/statuses?limit=40&exclude_replies=true&exclude_reblogs=true`,
      { headers: this.headers },
    );
    if (!res.ok) throw new Error(`Reading Mastodon statuses failed: ${res.status}`);
    for (const s of await res.json()) {
      if (s.card?.url) urls.add(s.card.url);
      for (const m of s.content.matchAll(/href="([^"]+)"/g)) urls.add(m[1]);
    }
    return urls;
  },

  async publish(post) {
    // Mastodon counts any URL as 23 characters.
    const text = postText(post, 500 - 25) + `\n\n${post.url}`;
    if (DRY_RUN) return { text, url: "(dry run)" };
    const res = await fetch(`${this.base}/api/v1/statuses`, {
      method: "POST",
      headers: { ...this.headers, "content-type": "application/json", "idempotency-key": post.url },
      body: JSON.stringify({ status: text, visibility: "public", language: post.lang || "en" }),
    });
    if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
    return { text, url: (await res.json()).url };
  },
};

// Add more targets here: anything with enabled / init / alreadyShared / publish.
const TARGETS = [bluesky, mastodon];

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  const feed = await loadFeed();
  const since = feed.since ? new Date(feed.since) : new Date(0);
  const now = new Date();

  const candidates = feed.posts.filter(
    (p) =>
      p.syndicate !== false &&
      new Date(p.pubDate) >= since &&
      new Date(p.pubDate) <= now &&
      (!ONLY || p.id === ONLY),
  );

  log(`${feed.posts.length} posts on site, ${candidates.length} eligible (published since ${since.toISOString().slice(0, 10)}, not opted out).`);
  if (DRY_RUN) log("DRY RUN: nothing will be posted.\n");

  let failed = false;

  for (const target of TARGETS) {
    // A Bluesky dry run works without a password: reading your feed is public.
    const usable = target.enabled(feed) || (DRY_RUN && target === bluesky && feed.bluesky?.handle);
    if (!usable) {
      log(`- ${target.name}: not configured, skipping.`);
      continue;
    }
    try {
      await target.init(feed);
      const shared = await target.alreadyShared();
      const todo = candidates.filter((p) => !shared.has(p.url));
      log(`- ${target.name}: ${todo.length} to post.`);

      for (const post of todo) {
        if (!(await waitUntilLive(post.url))) {
          log(`  ! ${post.id}: page not reachable yet, will retry next run.`);
          continue;
        }
        try {
          const res = await target.publish(post, feed);
          log(`  ✓ ${post.id} → ${res.url}\n    ${res.text.replace(/\n/g, "\n    ")}`);
          summary.push(`| ${target.name} | [${post.title}](${post.url}) | ${res.url} |`);
        } catch (e) {
          failed = true;
          log(`  ✗ ${post.id}: ${e.message}`);
          summary.push(`| ${target.name} | ${post.title} | failed: ${e.message} |`);
        }
      }
    } catch (e) {
      failed = true;
      log(`- ${target.name}: ${e.message}`);
    }
  }

  if (process.env.GITHUB_STEP_SUMMARY && summary.length) {
    await appendFile(
      process.env.GITHUB_STEP_SUMMARY,
      `### Syndication\n\n| Where | Post | Result |\n|---|---|---|\n${summary.join("\n")}\n`,
    );
  }
  if (failed) process.exit(1);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
